style.css:
/* Wallpaper KAngel - NSO Style */
body {
    background: linear-gradient(135deg, #ffb6f9, #aee8ff, #ffffff);
    background-size: cover;
    color: #ff66cc;
    font-family: "Comic Sans MS", "Arial", sans-serif;
}

/* Efeito brilho geral */
* {
    text-shadow: 0 0 5px #fff, 0 0 10px #ff99dd;
}

/* Painéis transparentes */
div, section, main {
    background: rgba(255, 255, 255, 0.15) !important;
    border: 2px solid #ff99dd;
    border-radius: 16px;
    backdrop-filter: blur(8px);
}

/* Botões fofos */
button {
    background: #ff99dd !important;
    color: white !important;
    border-radius: 12px;
    border: none;
    box-shadow: 0 0 10px #ff66cc;
    transition: 0.3s;
}

button:hover {
    background: #66d9ff !important;
    box-shadow: 0 0 15px #66d9ff;
}

/* Imagem central da KAngel */
body::before {
    content: "";
    position: fixed;
    top: 50%;
    left: 50%;
    width: 400px;
    height: 400px;
    transform: translate(-50%, -50%);
    background: url("https://i.imgur.com/zl0M6GQ.png") no-repeat center;
    background-size: contain;
    opacity: 0.35;
    pointer-events: none;
    z-index: -1;
}
